package service;
import database.DatabaseConnection;import model.AccountStatus;import org.mindrot.jbcrypt.BCrypt;import java.sql.*;import java.util.*;
/** Administrator operations require a verified, database-backed session. */
public final class AdminService {
 public static final class Session {private final long id;private Session(long id){this.id=id;}}
 public Session login(String username,String password){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT administrator_id,password_hash FROM administrators WHERE username=? AND active=TRUE")){p.setString(1,username);try(ResultSet r=p.executeQuery()){if(!r.next()||password==null||!BCrypt.checkpw(password,r.getString(2)))throw new SecurityException("Administrator authentication failed.");return new Session(r.getLong(1));}}catch(SQLException e){throw new IllegalStateException("Administrator login failed; verify database setup.",e);}}
 private void require(Connection c,Session session)throws SQLException{if(session==null)throw new SecurityException("Administrator session required.");try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM administrators WHERE administrator_id=? AND active=TRUE")){p.setLong(1,session.id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SecurityException("Administrator session is no longer active.");}}}
 public List<AdminAccount> search(Session session,String term){String q=term==null?"":term.trim();List<AdminAccount> out=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection()){require(c,session);try(PreparedStatement p=c.prepareStatement("SELECT a.account_number,c.full_name,c.mobile_number,a.account_type,a.balance,a.status,a.opening_date FROM accounts a JOIN customers c ON c.customer_id=a.customer_id WHERE a.account_number LIKE ? OR c.full_name LIKE ? ORDER BY c.full_name,a.account_number LIMIT 200")){p.setString(1,"%"+q+"%");p.setString(2,"%"+q+"%");try(ResultSet r=p.executeQuery()){while(r.next())out.add(new AdminAccount(r.getString(1),r.getString(2),r.getString(3),model.AccountType.valueOf(r.getString(4)),r.getBigDecimal(5),AccountStatus.valueOf(r.getString(6)),r.getDate(7).toLocalDate()));}}return out;}catch(SQLException e){throw new IllegalStateException("Account search failed.",e);}}
 public void closeAccount(Session session,String account){try(Connection c=DatabaseConnection.getConnection()){require(c,session);c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("SELECT balance,status FROM accounts WHERE account_number=? FOR UPDATE")){p.setString(1,account);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Account not found.");if(r.getBigDecimal(1).signum()!=0)throw new IllegalStateException("Account must have zero balance before closure.");if(!"ACTIVE".equals(r.getString(2)))throw new IllegalStateException("Account is already closed.");}}try(PreparedStatement p=c.prepareStatement("UPDATE accounts SET status='CLOSED' WHERE account_number=?")){p.setString(1,account);p.executeUpdate();}c.commit();}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("Administrative account closure failed.",e);}}
}
